package com.tv.simplelive;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.*;
import java.io.*;import java.net.*;import java.lang.reflect.*;import java.util.*;import java.util.concurrent.*;
import org.videolan.libvlc.*;
public final class UiChecks extends Instrumentation {
 MainActivity activity;int checks;StringBuilder log=new StringBuilder();File output;ServerSocket stalled;
 public void onCreate(Bundle args){super.onCreate(args);start();}
 void require(boolean value,String label){if(!value)throw new AssertionError(label);checks++;log.append("PASS ").append(label).append('\n');Bundle progress=new Bundle();progress.putString("stream","PASS "+label+"\n");sendStatus(0,progress);}
 Object field(String name)throws Exception{Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);return f.get(activity);}
 void set(String name,Object value)throws Exception{Field f=MainActivity.class.getDeclaredField(name);f.setAccessible(true);f.set(activity,value);}
 Object raw(String name,Class<?>[] types,Object...args)throws Exception{Method m=MainActivity.class.getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(activity,args);}
 void ui(final String name,final Class<?>[] types,final Object...args){runOnMainSync(new Runnable(){public void run(){try{raw(name,types,args);}catch(Exception e){throw new RuntimeException(e);}}});waitForIdleSync();}
 @SuppressWarnings("unchecked") ArrayList<Playlist.Channel> channels()throws Exception{return(ArrayList<Playlist.Channel>)field("channels");}
 @SuppressWarnings("unchecked") ArrayList<String> names()throws Exception{return(ArrayList<String>)field("names");}
 void open()throws Exception{
  getTargetContext().getSharedPreferences("settings",0).edit().putBoolean("autoInspect",false).commit();
  String day=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());getTargetContext().getSharedPreferences("appUpdate",0).edit().putInt("sourceRevision",2).putString("attemptDay",day).commit();
  activity=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));waitForIdleSync();
  runOnMainSync(new Runnable(){public void run(){try{channels().clear();for(int i=0;i<30;i++)channels().add(new Playlist.Channel("验收频道"+i,"http://127.0.0.1:"+stalled.getLocalPort()+"/route"+i,"fixture"));set("source","fixture://live137");set("inspectionForeground",true);set("inspectionGeneration",10);set("index",-1);set("inspectionSummary","逐源更新验收");}catch(Exception e){throw new RuntimeException(e);}}});ui("updateList",new Class<?>[0]);ui("showPanel",new Class<?>[]{boolean.class},true);
 }
 SourceInspector.Entry entry(int index)throws Exception{SourceInspector.Health h=new SourceInspector.Health();h.ok=true;h.tested=true;h.testedAt=System.currentTimeMillis();h.samples=8;h.frames=30;h.headroom=2.5;h.state="优选 2.50倍 · 30帧 · 已测1/3";return new SourceInspector.Entry(new Playlist.Channel("验收频道"+index,"http://127.0.0.1:"+stalled.getLocalPort()+"/qualified"+index,"fixture"),h);}
 void screenshot(String name)throws Exception{waitForIdleSync();Thread.sleep(150);Bitmap image=getUiAutomation().takeScreenshot();require(image!=null,"screenshot captured: "+name);try(OutputStream out=new FileOutputStream(new File(output,name))){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();}
 int selectedTop(ListView list){View child=list.getChildAt(list.getSelectedItemPosition()-list.getFirstVisiblePosition());return child==null?Integer.MIN_VALUE:child.getTop();}
 void desktop()throws Exception{long until=SystemClock.elapsedRealtime()+4000;String text="";while(SystemClock.elapsedRealtime()<until){try(ParcelFileDescriptor fd=getUiAutomation().executeShellCommand("dumpsys activity activities");InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(fd);ByteArrayOutputStream bytes=new ByteArrayOutputStream()){byte[] b=new byte[8192];for(int n;(n=in.read(b))!=-1;)bytes.write(b,0,n);text=bytes.toString("UTF-8");}boolean ours=false,hasTop=false;for(String line:text.split("\n"))if(line.contains("mResumedActivity")||line.contains("topResumedActivity")){hasTop=true;ours|=line.contains("com.tv.simplelive/");}if(hasTop&&!ours)break;Thread.sleep(100);}boolean ours=false,home=false;for(String line:text.split("\n"))if(line.contains("mResumedActivity")||line.contains("topResumedActivity")){ours|=line.contains("com.tv.simplelive/");home|=line.toLowerCase(Locale.US).contains("launcher");}require(!ours&&home,"Home intent resumes launcher instead of reopening TV app");require(activity.isFinishing(),"TV activity finishes and removes its task");}
 public void onStart(){Bundle result=new Bundle();CountDownLatch releaseStop=new CountDownLatch(1);
  try{
   output=getTargetContext().getExternalFilesDir("live137qa");output.mkdirs();stalled=new ServerSocket(0,32,InetAddress.getByName("127.0.0.1"));open();
   final ListView list=(ListView)field("list");runOnMainSync(()->{list.setSelectionFromTop(15,120);list.requestFocus();});waitForIdleSync();Thread.sleep(150);int selected=list.getSelectedItemPosition(),top=selectedTop(list);SourceInspector.Entry measured=entry(15);int generation=(Integer)field("loadGeneration");raw("showInspectionEntry",new Class<?>[]{SourceInspector.Entry.class,int.class,int.class,String.class},measured,10,generation,"fixture://live137");waitForIdleSync();Thread.sleep(100);
   require(names().get(15).contains("已测1/3"),"individual route quality appears immediately in channel row");require(list.getSelectedItemPosition()==selected&&Math.abs(selectedTop(list)-top)<=1,"incremental row update preserves selected row and viewport");require(list.hasFocus(),"quality update does not steal remote focus");
   String key=(String)raw("checkpointKey",new Class<?>[0]);raw("saveInspectionEntry",new Class<?>[]{SourceInspector.Entry.class,String.class,boolean.class,int.class},measured,key,false,10);
   Map<?,?> finalRecords=(Map<?,?>)raw("checkpoints",new Class<?>[0]);Map<?,?> partialRecords=(Map<?,?>)raw("checkpoints",new Class<?>[]{String.class},key+":visible");require(finalRecords.isEmpty()&&partialRecords.size()==1,"visible partial quality persists separately from completed comparison");
   final String oldName=names().get(15);SourceInspector.Entry late=entry(15);late.health.state="stale callback must not appear";raw("showInspectionEntry",new Class<?>[]{SourceInspector.Entry.class,int.class,int.class,String.class},late,9,generation,"fixture://live137");waitForIdleSync();require(names().get(15).equals(oldName),"late callbacks from cancelled scans cannot replace current row");
   raw("showInspectionEntry",new Class<?>[]{SourceInspector.Entry.class,int.class,int.class,String.class},late,10,generation,"fixture://other-source");waitForIdleSync();require(names().get(15).equals(oldName),"callbacks from other playlists cannot change this list");
   final Button fullHome=(Button)field("homeButton");require(fullHome.isShown()&&((View)field("panel")).getWidth()==activity.getWindow().getDecorView().getWidth(),"return-to-desktop button is present in full-width list");screenshot("full-list-progress.png");
   runOnMainSync(()->{list.setSelection(29);list.requestFocus();});waitForIdleSync();sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_DOWN);waitForIdleSync();require(fullHome.hasFocus(),"D-pad reaches desktop button below the final channel");
   runOnMainSync(()->fullHome.performClick());waitForIdleSync();desktop();
   open();ui("startInspection",new Class<?>[]{boolean.class},false);require(names().get(15).contains("已测1/3"),"automatic inspection restores partial quality before all routes finish");ui("cancelInspection",new Class<?>[0]);
   final CountDownLatch stopStarted=new CountDownLatch(1);final MediaPlayer slow=new MediaPlayer((LibVLC)field("vlc")){public void stop(){stopStarted.countDown();try{releaseStop.await(8,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}super.stop();}};
   runOnMainSync(()->{try{set("player",slow);set("index",1);}catch(Exception e){throw new RuntimeException(e);}});ui("showPanel",new Class<?>[]{boolean.class},true);final Button sideHome=(Button)field("homeButton");require(sideHome.isShown()&&((View)field("panel")).getWidth()<activity.getWindow().getDecorView().getWidth(),"return-to-desktop button is present in side list");SourceInspector.Entry sideEntry=entry(1);raw("showInspectionEntry",new Class<?>[]{SourceInspector.Entry.class,int.class,int.class,String.class},sideEntry,(Integer)field("inspectionGeneration"),(Integer)field("loadGeneration"),"fixture://live137");waitForIdleSync();screenshot("side-list-progress.png");
   runOnMainSync(()->sideHome.performClick());waitForIdleSync();require(stopStarted.await(2,TimeUnit.SECONDS),"native player stop runs on cleanup worker");desktop();require(releaseStop.getCount()==1,"desktop return does not wait for a blocked native stop");releaseStop.countDown();
   open();final MediaPlayer idle=new MediaPlayer((LibVLC)field("vlc"));runOnMainSync(()->{try{set("player",idle);set("index",0);}catch(Exception e){throw new RuntimeException(e);}});ui("showPanel",new Class<?>[]{boolean.class},false);sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);waitForIdleSync();require(((View)field("panel")).getVisibility()==View.VISIBLE,"first Back opens side list from fullscreen playback");sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);waitForIdleSync();desktop();
   open();sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);waitForIdleSync();desktop();
   log.append("RESULT PASS checks=").append(checks).append("; Android TV API36 x86 test build; no physical TV claim\n");result.putString("result","PASS");
  }catch(Throwable e){result.putString("result","FAIL");log.append("ERROR ").append(android.util.Log.getStackTraceString(e));}
  finally{releaseStop.countDown();if(stalled!=null)try{stalled.close();}catch(IOException ignored){}if(activity!=null&&!activity.isFinishing())runOnMainSync(()->activity.finish());try{if(output!=null)try(OutputStream out=new FileOutputStream(new File(output,"results.txt"))){out.write(log.toString().getBytes("UTF-8"));}}catch(IOException ignored){}}
  result.putString("stream",log.toString());finish("PASS".equals(result.getString("result"))?-1:1,result);
 }
}
